/** Saved gameplay selections and known life-saving effect names, preserving absent fields. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LifeSavingEffectName, RuntimeControlsSaveExtract
 * depends    src/save/runtime-controls/constants
 * used by    src/save/runtime-controls/index, src/save/runtime-controls/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { LIFE_SAVING_EFFECT_NAMES_BY_ID } from './constants'

export type LifeSavingEffectName = typeof LIFE_SAVING_EFFECT_NAMES_BY_ID[keyof typeof LIFE_SAVING_EFFECT_NAMES_BY_ID]

export interface RuntimeControlsSaveExtract {
  rangeLevelSelected: number | null
  swampRangeLevelSelected: number | null
  poisonSwampStunOff: boolean | null
  innerOrbDistance: number | null
  workshopOrbDistance: number | null
  savedWorkshopOrbDistance: number | null
  savedInnerOrbDistance: number | null
  /** Raw ordered IDs; decodeLifeSavingOrder provides fragment-proven names. */
  lifeSavingOrder: number[] | null
  /** Raw saved switch; effect semantics are not inferred by this reader. */
  energyShieldRestrictionToggle: boolean | null
  /** Raw mode and list; their presence does not establish targeting behavior. */
  targetPriority: number | null
  targetPriorityList: number[] | null
  unreadableKeys: string[]
}
